#!/bin/sh
set -o pipefail 2>/dev/null || true # a failing spec or sim must fail the check even through "| tail -1"
# Syntax-checks every script and runs the tests. Needs Lune 0.10.5 on PATH or in /root/bin.
cd "$(dirname "$0")/.." || exit 1
LUNE=$(command -v lune || echo /root/bin/lune)
"$LUNE" run tools/syntax.luau && "$LUNE" run tests/RoundRules.spec.luau && "$LUNE" run tests/CarryMath.spec.luau && "$LUNE" run tests/GirlMotion.spec.luau | tail -1 && "$LUNE" run tests/GirlMoves.spec.luau | tail -1 && "$LUNE" run tests/StabMotion.spec.luau | tail -1 && "$LUNE" run tests/DownMotion.spec.luau | tail -1 && "$LUNE" run tests/Movement.spec.luau | tail -1 && "$LUNE" run tests/Locomotion.spec.luau | tail -1 && "$LUNE" run tests/PlayerMoves.spec.luau | tail -1 && "$LUNE" run tests/GirlRoll.spec.luau && "$LUNE" run tests/CrateRoll.spec.luau && "$LUNE" run tests/SpinWheel.spec.luau && "$LUNE" run tests/Leaderboards.spec.luau && "$LUNE" run tests/Knives.spec.luau && "$LUNE" run tests/KnifeWear.spec.luau && "$LUNE" run tests/KnifeShapes.spec.luau && "$LUNE" run tests/Sounds.spec.luau && "$LUNE" run tests/SetupKnives.spec.luau && "$LUNE" run tests/AdminRules.spec.luau | tail -1 && "$LUNE" run tests/StandShowcase.spec.luau | tail -1 && "$LUNE" run tests/LobbyLayout.spec.luau && "$LUNE" run tests/SetupLobbyProps.spec.luau && (cd .. && "$LUNE" run huzz-valley/tools/sim/round_sim.luau | tail -1)
